import{_ as i,o as a,c as e,a2 as n}from"./chunks/framework.D66Xq0Kv.js";const c=JSON.parse('{"title":"4. Symbolic Shapes and Constraints","description":"","frontmatter":{},"headers":[],"relativePath":"spec/04-shapes-constraints.md","filePath":"spec/04-shapes-constraints.md","lastUpdated":null}'),t={name:"spec/04-shapes-constraints.md"};function p(l,s,h,o,r,d){return a(),e("div",null,[...s[0]||(s[0]=[n(`<h1 id="_4-symbolic-shapes-and-constraints" tabindex="-1">4. Symbolic Shapes and Constraints <a class="header-anchor" href="#_4-symbolic-shapes-and-constraints" aria-label="Permalink to &quot;4. Symbolic Shapes and Constraints&quot;">​</a></h1><h2 id="_4-1-dimension-expressions" tabindex="-1">4.1 Dimension expressions <a class="header-anchor" href="#_4-1-dimension-expressions" aria-label="Permalink to &quot;4.1 Dimension expressions&quot;">​</a></h2><p>A tensor dimension is a non-negative compile-time integer expression.</p><p>Supported expression forms:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>constant</span></span>
<span class="line"><span>symbol</span></span>
<span class="line"><span>A + B</span></span>
<span class="line"><span>A - B</span></span>
<span class="line"><span>A * B</span></span>
<span class="line"><span>A / B</span></span>
<span class="line"><span>A % B</span></span>
<span class="line"><span>min(A, B)</span></span>
<span class="line"><span>max(A, B)</span></span></code></pre></div><p>Division in a dimension expression is integer division and is valid only when its semantics are statically well-defined for the operation being checked. Library code SHOULD state divisibility constraints when exact division is intended.</p><h2 id="_4-2-compile-time-constants" tabindex="-1">4.2 Compile-time constants <a class="header-anchor" href="#_4-2-compile-time-constants" aria-label="Permalink to &quot;4.2 Compile-time constants&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>const Hidden = 4096</span></span>
<span class="line"><span>const Heads = 32</span></span>
<span class="line"><span>const HeadDim = Hidden / Heads</span></span></code></pre></div><p>Compile-time constants MUST be pure and evaluable without runtime tensor data.</p><h2 id="_4-3-where-constraints" tabindex="-1">4.3 <code>where</code> constraints <a class="header-anchor" href="#_4-3-where-constraints" aria-label="Permalink to &quot;4.3 \`where\` constraints&quot;">​</a></h2><div class="language-linnet vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">linnet</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">fn</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> split_heads</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&lt;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">H</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">Dim</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">N</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">Dim</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(...)</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">    -&gt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> ...</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">where</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">    H</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> %</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> N</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> ==</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 0</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">    N</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &gt;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 0</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    ...</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p>Supported relational forms in the initial specification:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>== != &lt; &lt;= &gt; &gt;=</span></span></code></pre></div><p>Arithmetic expressions may appear on either side.</p><h2 id="_4-4-proof-requirement" tabindex="-1">4.4 Proof requirement <a class="header-anchor" href="#_4-4-proof-requirement" aria-label="Permalink to &quot;4.4 Proof requirement&quot;">​</a></h2><p>When an operation requires two dimensions to match, the compiler MUST prove the equality from:</p><ul><li>syntactic identity;</li><li>constant evaluation;</li><li>generic substitutions;</li><li>declared constraints;</li><li>solver deductions that are sound under the specification.</li></ul><p>If the compiler cannot prove a required relation, strict static checking fails. A backend&#39;s ability to guard or dynamically handle the case does not make the Linnet program valid.</p><h2 id="_4-5-solver-completeness" tabindex="-1">4.5 Solver completeness <a class="header-anchor" href="#_4-5-solver-completeness" aria-label="Permalink to &quot;4.5 Solver completeness&quot;">​</a></h2><p>The language does not require an implementation to decide every true nonlinear integer proposition. A conforming compiler MUST be sound; it may be incomplete.</p><p>When a required relationship is true but beyond the solver&#39;s supported reasoning, the compiler SHOULD emit a diagnostic suggesting an explicit <code>where</code> constraint or a simpler equivalent shape expression.</p><h2 id="_4-6-broadcasting" tabindex="-1">4.6 Broadcasting <a class="header-anchor" href="#_4-6-broadcasting" aria-label="Permalink to &quot;4.6 Broadcasting&quot;">​</a></h2><p>Elementwise tensor operations use statically provable right-aligned broadcasting.</p><p>For each aligned axis, dimensions are compatible when the compiler can prove either:</p><ul><li>the dimensions are equal; or</li><li>one dimension is exactly <code>1</code>.</li></ul><p>Example:</p><div class="language-linnet vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">linnet</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">Tensor</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">[</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">B</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">S</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">H</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">; </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">T</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">] </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">+</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> Tensor</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">[</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">H</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">; </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">T</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">    -&gt;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> Tensor</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">[</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">B</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">S</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">H</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">; </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">T</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span></code></pre></div><p>If symbolic compatibility cannot be proven, the operation is an error rather than a runtime guess.</p><p>Explicit broadcast operations in the tensor standard library may be used to state intent.</p><h2 id="_4-7-shape-packs" tabindex="-1">4.7 Shape packs <a class="header-anchor" href="#_4-7-shape-packs" aria-label="Permalink to &quot;4.7 Shape packs&quot;">​</a></h2><p>A shape pack can participate in generic suffix or prefix patterns:</p><div class="language-linnet vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">linnet</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">Tensor</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">[</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">*</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">S, </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">In</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">; </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">T</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span></code></pre></div><p>When matching against <code>Tensor[B, S, H; T]</code> with <code>In = H</code>, <code>*S</code> becomes <code>[B, S]</code>.</p><p>The same pack symbol within a signature denotes the same sequence of dimensions.</p><h2 id="_4-8-negative-and-zero-dimensions" tabindex="-1">4.8 Negative and zero dimensions <a class="header-anchor" href="#_4-8-negative-and-zero-dimensions" aria-label="Permalink to &quot;4.8 Negative and zero dimensions&quot;">​</a></h2><p>Concrete tensor dimensions MUST be non-negative. Operations may impose stronger constraints such as <code>N &gt; 0</code>.</p><p>A compile-time expression proven negative is an error.</p>`,37)])])}const g=i(t,[["render",p]]);export{c as __pageData,g as default};
